def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest horizontal run of non-background cells.
    best = None
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if best is None or c - start > best[2] - best[1]:
                best = (r, start, c)

    out = [row[:] for row in grid]
    if best is not None:
        r, start, end = best
        if r + 1 < h:
            for c in range(start, end):
                color = grid[r][c]
                out[r][c] = bg
                out[r + 1][c] = color
    return out
